enum Command { Place(OrderId, u32), Cancel(OrderId) }
fn worker(rx: Receiver<Command>, repo: Arc<Repo>) {      // executor
    while let Ok(cmd) = rx.recv() {                      // Err => all senders dropped
        match cmd {
            Command::Place(id, qty) => repo.place(id, qty),
            Command::Cancel(id) => repo.cancel(id),
        }
    }
}
let (tx, rx) = mpsc::sync_channel::<Command>(256);       // bounded == backpressure
tx.send(Command::Place(id, 2)).unwrap();                 // invocation only

