let (tx, mut rx) = tokio::sync::mpsc::channel::<Command>(256);   // bounded
tokio::spawn(async move {                              // executor task
    while let Some(cmd) = rx.recv().await {
        match cmd {
            Command::Place(id, qty) => repo.place(id, qty).await,
            Command::Cancel(id) => repo.cancel(id).await,
        }
    }
});
